class AdminApiException(Exception):
    """Admin API base exception."""


class AdminApiTerminatedException(AdminApiException):
    """AdminApiTerminatedException is raised when Admin API process is terminated."""


class AdminApiVersionMismatchException(AdminApiException):
    """AdminApiVersionMismatchException is raised when Admin API is incompatibile with current CLI."""


class AdminApiConnectionClosedException(AdminApiException):
    """AdminApiConnectionClosedException is raised when Admin API connection is broken."""


class AdminApiNoResponseException(AdminApiException):
    """AdminApiNoResponseException is raised when Admin API does not responsd to request."""


class AdminApiProcedureFailureException(AdminApiException):
    """AdminApiProcedureFailureException is raised when procedure ends with failed status."""

    def __init__(self, message=None, error_code=None):
        self.error_code = error_code
        self.message = message
        super(AdminApiProcedureFailureException, self).__init__(self.message)


class AdminApiProcedureTimeoutException(AdminApiException):
    """AdminApiProcedureTimeoutException is raised when procedure does not reach completed status within timeout."""
